(function(){
  // امنع autoplay أول 8 ثواني
  window._block=true;
  let orig=HTMLMediaElement.prototype.play;
  HTMLMediaElement.prototype.play=function(){
    if(window._block && this.currentTime<0.5 && this.id!=='v109-salawat'){
      return Promise.reject('blocked');
    }
    return orig.call(this);
  };
  setTimeout(()=>{window._block=false;},8000);

  // احذف البار لو ظهر
  function kill(){
    document.querySelectorAll('div').forEach(d=>{
      let t=d.textContent||'';
      if(t.includes('تعمل الآن') && t.includes('محمود علي البنا')){
        let p=d;
        for(let i=0;i<7;i++){
          if(p&&p.textContent&&p.textContent.includes('محمود علي البنا')&&p.textContent.length<1200){
            p.remove();
            break;
          }
          p=p.parentElement;
        }
      }
    });
  }
  setInterval(kill, 100);
})();
